ac01\ud558\ub358 \ub54c\uac00 \uc788\uc5c8\ub294\ub370\nVPL\uc5d0\ub294 \ud070\uae00\uc790\ucc45\ub3c4 \ub530\ub85c \uc788\uace0\n\uc624\ub514\uc624\ubd81\ub3c4 CD\u00b7MP3 CD\u00b7\ub2e4\uc6b4\ub85c\ub4dc \uac19\uc740 \ud615\uc2dd\uc73c\ub85c \ub098\ub258\uc5b4 \uc788\ub124\n\uc601\ud654\ub098 TV \ud504\ub85c\uadf8\ub7a8\uc740 \uc74c\uc131\ud574\uc124\uc774 \uc788\ub294 DVD\u00b7\ube14\ub8e8\ub808\uc774 \uc790\ub8cc\ub3c4 \uc788\uc5b4\n\ub098\ub294 \ubb58 \uc77d\uc744\uc9c0\ub9cc\ud07c \uc5b4\ub5a4 \ubc29\uc2dd\uc774 \ud3b8\ud55c\uc9c0\ub3c4 \uc880 \ub354 \uc0dd\uac01\ud574\ubcf4\ub824\ub294 \uc911", "expected_views": 12, "old_view_pulses": [{"views": 12, "bucket": "2026-10-07T05:30:00+00:00"}]}, {"id": "94cb77a7-5fa9-43a5-a643-aded5aa2f9db", "old_created_at": "2026-10-06 19:36:00+00", "new_created_at": "2026-10-07T16:19:40.070020+00:00", "author_id": "10000000-0000-0000-0000-000000000066", "city_id": "vancouver", "expected_title": "\ubc34\ucfe0\ubc84 \uadf8\ub9b0\uc6e8\uc774\ub294 \uc790\uc804\uac70\ub9cc \ud0c0\ub294 \uae38\uc774 \uc544\ub2c8\ub124", "expected_body": "\uac77\ub294 \uc0ac\ub78c, \uc790\uc804\uac70 \ud0c0\ub294 \uc0ac\ub78c, \ud720\uccb4\uc5b4\ub85c \uc6c0\uc9c1\uc774\ub294 \uc0ac\ub78c\uc740 \uac19\uc740 \ub3d9\ub124\uc5d0\uc11c\ub3c4 \ud544\uc694\ud55c \uae38\uc774 \ub2e4\ub984\n\ubc34\ucfe0\ubc84 \uadf8\ub9b0\uc6e8\uc774\ub294 \uac77\uae30\u00b7\uc790\uc804\uac70\u00b7\ubc14\ud034 \uc774\ub3d9\uc744 \uc704\ud55c \uad50\ud1b5 \uc5f0\uacb0\ub9dd\uc774\uc57c\n\ucc28 \ud1b5\ud589\uc744 \uc904\uc774\uac70\ub098 \ucc28\uac00 \uc5c6\ub294 \uad6c\uac04\uc73c\ub85c \uacf5\uacf5 \uacf5\uac04\uacfc \uc790\uc5f0 \uacf5\uac04\uc744 \uc774\uc5b4\n\ubb3c\uac00 \uc0b0\ucc45\uae38\ubfd0 \uc544\ub2c8\ub77c \ub3d9\ub124 \uac70\ub9ac\ub098 \uc790\uc5f0 \uc0b0\ucc45\ub85c\ub3c4 \uc5ec\uae30\uc5d0 \ub4e4\uc5b4\uac00\uace0\n\ub09c \ud658\uc2b9\uc5ed\ub9cc \ucc0d\ub358 \uc9c0\ub3c4\uc5d0 \uac78\uc5b4\uc11c \uc774\uc5b4\uac08 \uae38\ub3c4 \uac19\uc774 \ub123\uc744 \uac70\uc57c", "expected_views": 3, "old_view_pulses": [{"views": 3, "bucket": "2026-10-06T19:30:00+00:00"}]}, {"id": "b62cb45a-c691-4fb9-8ae7-3e80a5fae468", "old_created_at": "2026-10-06 23:07:00+00", "new_created_at": "2026-10-07T16:12:39.070020+00:00", "author_id": "10000000-0000-0000-0000-000000000031", "city_id": "toronto", "expected_title": "\uae38\ub4dc\ud30c\ud06c\uc5d4 \uc61b \uac74\ubb3c\uc758 \uc870\uac01\ub4e4\ub3c4 \ubaa8\uc5ec \uc788\ub124", "expected_body": "\uc624\ub798\ub41c \uac74\ubb3c\uc740 \ud1b5\uc9f8\ub85c \ub0a8\uc544\uc57c \ubcfc \uc218 \uc788\ub294 \uc904 \uc54c\uc558\ub294\ub370, \uae38\ub4dc\ud30c\ud06c\uc564\uac00\ub4e0\uc2a4\uc5d4 \uacf5\uacf5\ubbf8\uc220\uc774\ub791 \uac74\ucd95 \uc870\uac01\ub4e4\uc774 \ud568\uaed8 \uc788\uc74c\n\uc2a4\uce74\ubcf4\ub85c \ube14\ub7ec\ud504 \uc704 \uc232\uacfc \uc815\uc6d0\uc5d0 \uc774\ub7f0 \ud754\uc801\ub3c4 \ub0a8\uc544 \uc788\ub2e4\ub2c8, \uc0b0\ucc45 \ud6c4\ubcf4\uc5d0 \ub123\uc744 \uac70\uc57c (\ub0b4 \uc5ed\uc0ac \uacf5\ubd80\ub3c4 \ub2e4\ub9ac\ub85c \uc880 \ud574\uc57c\uaca0\ub124 \u314b\u314b)", "expected_views": 3, "old_view_pulses": [{"views": 3, "bucket": "2026-10-06T23:00:00+00:00"}]}, {"id": "f3494786-dc95-440b-9a35-6f2954dfd4ea", "old_created_at": "2026-10-06 22:11:00+00", "new_created_at": "2026-10-07T16:05:38.070020+00:00", "author_id": "10000000-0000-0000-0000-000000000033", "city_id": "toronto", "expected_title": "\ubc24 TTC \ubc84\uc2a4\uc5d0\uc120 \uc815\ub958\uc7a5 \uc0ac\uc774 \ud558\ucc28\ub97c \uc694\uccad\ud560 \uc218\ub3c4 \uc788\ub124", "expected_body": "\ubc24\uc5d0 \ud63c\uc790 \ubc84\uc2a4\uc5d0\uc11c \ub0b4\ub9ac\ub294 \uc0ac\ub78c\uc740 \ub0b4\ub824\uc11c \uac77\ub294 \uae38\ub3c4 \uc2e0\uacbd \uc4f0\uaca0\ub124, \ub09c \ub178\uc120\ub9cc \uc0dd\uac01\ud588\uc74c\nTTC\ub294 \ubc24 9\uc2dc\ubd80\ud130 \uc0c8\ubcbd 5\uc2dc\uae4c\uc9c0 \ud63c\uc790 \ubc84\uc2a4\ub97c \ud0c0\uba70 \ubd88\uc548\uc744 \ub290\ub07c\ub294 \uc2b9\uac1d\uc774 \uc815\ub958\uc7a5 \uc0ac\uc774 \ud558\ucc28\ub97c \uc694\uccad\ud560 \uc218 \uc788\uc5b4, \uae30\uc0ac\uac00 \uc548\uc804\ud558\uac8c \uc124 \uc218 \uc788\uc5b4\uc57c \ud558\uace0 \uc804\ucc28\uc5d4 \uc801\uc6a9 \uc548 \ub428\n\uc774\uc6a9 \uc808\ucc28\ub294 \ubc14\ub014 \uc218 \uc788\uc73c\ub2c8 \ub2e4\uc2dc \ud655\uc778\ud558\ub824\uace0, \uac19\uc774 \uadc0\uac00\ud560 \ub550 \ub0b4\ub824\uc11c \uac77\ub294 \uae38 \uc598\uae30\ub3c4 \ud574\ubcfc\uae4c \ud574", "expected_views": 20, "old_view_pulses": [{"views": 20, "bucket": "2026-10-06T22:10:00+00:00"}]}, {"id": "e5cf66a2-a518-4955-8a59-a604f4690e2f", "old_created_at": "2026-10-06 23:28:00+00", "new_created_at": "2026-10-07T15:58:37.070020+00:00", "author_id": "10000000-0000-0000-0000-000000000037", "city_id": "toronto", "expected_title": "\ud1a0\ub860\ud1a0 \ubba4\uc9c1\uac00\ub4e0\uc740 \ubc14\ud750 \uc74c\uc545\uc744 \uc815\uc6d0\uc73c\ub85c \uc62e\uae34 \uac70\ub124", "expected_body": "\ud1a0\ub860\ud1a0 \ubba4\uc9c1\uac00\ub4e0 \ucc98\uc74c \uc54c\uc544\ubcf4\ub294\ub370 \uc774\ub984\ub9cc \ubcf4\uace0 \uc74c\uc545 \ud2c0\uc5b4\ub193\ub294 \uacf5\uc6d0\uc778 \uc904 \ud63c\uc790 \uc0c1\uc0c1\ud568 \u314b\u314b\n\uc5ec\uae34 \uccbc\ub9ac\uc2a4\ud2b8 \uc694\uc694\ub9c8\uc5d0\uac8c\uc11c \uc601\uac10\uc744 \ubc1b\uc544 \ubc14\ud750 \ubaa8\uc74c\uace1\uc744 \uc2dd\ubb3c\uacfc \uc815\uc6d0 \uc694\uc18c\ub85c \ud45c\ud604\ud55c \uacf5\uac04\uc774\uc57c\n\uc74c\uc545\uc744 \ub4e3\ub294 \uac83 \ub9d0\uace0 \ud48d\uacbd\uc73c\ub85c \ud480\uc5b4\ub0b8\ub2e4\ub294 \uac8c \uc2e0\uae30\ud574\uc11c, \ub3d9\ub124 \uc774\ub984 \uc678\uc6b0\ub294 \uc7ac\ubbf8\uac00 \ud558\ub098 \ub298\uc5c8\uc74c", "expected_views": 1, "old_view_pulses": [{"views": 1, "bucket": "2026-10-06T23:20:00+00:00"}]}, {"id": "c668b778-5fa1-4e3e-9a35-8b162e9dc93d", "old_created_at": "2026-10-06 17:41:00+00", "new_created_at": "2026-10-07T15:51:36.070020+00:00", "author_id": "10000000-0000-0000-0000-000000000036", "city_id": "toronto", "expected_title": "TPL \uc5b8\uc5b4\ud559\uc2b5 \ubaa9\ub8