d68d\uc774\ub791 \ud0c0\ub824\ub294 \uad50\ud1b5\ud3b8 \ucd94\uc801\uc744 \uac19\uc774 \ub2e4\ub8e8\ub124\n\uc774\uc6a9 \uc548\ub0b4\ub294 \ubc14\ub014 \uc218 \uc788\uc73c\ub2c8 \uc4f0\uae30 \uc804\uc5d0 \ub2e4\uc2dc \ud655\uc778\ud558\ub824\uace0, \uc774\ub7f0 \uc571 \ubcfc \ub54c \ub3c4\ucc29 \uc608\uc0c1\uc774\ub791 \uacbd\ub85c \uc911 \ubb58 \uba3c\uc800 \ubd10?", "expected_views": 4, "old_view_pulses": [{"views": 4, "bucket": "2026-10-07T00:10:00+00:00"}]}, {"id": "de04aea7-448e-457f-96d7-2a7429ad9bd8", "old_created_at": "2026-10-06 18:52:00+00", "new_created_at": "2026-10-07T14:06:21.070020+00:00", "author_id": "10000000-0000-0000-0000-000000000141", "city_id": "calgary", "expected_title": "\uce98\uac70\ub9ac \ub3c4\uc11c\uad00 \uadf8\ub9bc\ucc45\uc740 \uc5ec\ub7ec \uc5b8\uc5b4\ub85c \ub4e3\ub294 \uc790\ub8cc\ub3c4 \uc788\ub124", "expected_body": "\uadf8\ub9bc\ucc45\uc744 \uc18c\ub9ac \ub0b4 \uc77d\uc73c\ub824\ub2c8 \ub0b4\uac00 \uba3c\uc800 \ubc1c\uc74c \uc5f0\uc2b5\ubd80\ud130 \ud574\uc57c \ud560 \uac83 \uac19\uc74c \u314b\u314b\n\uce98\uac70\ub9ac \ub3c4\uc11c\uad00 LOTE4Kids\ub294 \uc601\uc5b4\u00b7\ud504\ub791\uc2a4\uc5b4\u00b7\uc2a4\ud398\uc778\uc5b4 \uac19\uc740 \uc5ec\ub7ec \uc5b8\uc5b4\uc758 \uadf8\ub9bc\ucc45\uc744 \uc77d\uace0 \ub4e3\ub294 \uc790\ub8cc\ub124\n\uac19\uc774 \ub4e4\uc744 \uc774\uc57c\uae30\ub97c \ud558\ub098 \uace8\ub77c\ubcf4\uace0 \uc2f6\uc740\ub370, \uadf8\ub9bc\ucc45\uc740 \uc775\uc219\ud55c \uc5b8\uc5b4\ub791 \ubc30\uc6b0\ub294 \uc5b8\uc5b4 \uc911 \ubb58\ub85c \ub4e4\uc73c\uba74 \ub354 \uc7ac\ubc0c\uc744\uae4c?", "expected_views": 16, "old_view_pulses": [{"views": 16, "bucket": "2026-10-06T18:50:00+00:00"}]}, {"id": "ea24febc-822c-4306-8909-fe596e565bd1", "old_created_at": "2026-10-06 19:43:00+00", "new_created_at": "2026-10-07T13:59:20.070020+00:00", "author_id": "10000000-0000-0000-0000-000000000128", "city_id": "calgary", "expected_title": "\uc0d8\ub9ac\ube59\uc2a4\ud134 \uc591\uc5b4\uc7a5\uc740 \uc1a1\uc5b4\uac00 \ud638\uc218\ub85c \uac00\uae30 \uc804 \uc790\ub77c\ub294 \uacf3\uc774\ub124", "expected_body": "\ubb3c\uace0\uae30\uac00 \ud638\uc218\uc5d0 \uc0ac\ub294 \ubaa8\uc2b5\ub9cc \uc0dd\uac01\ud588\ub294\ub370 \uc790\ub77c\ub294 \uae38\ub3c4 \ub530\ub85c \uc788\ub124\n\ubcf4\uc6b0\ud574\ube44\ud0c0\ud2b8\uc2a4\ud14c\uc774\uc158\uc758 \uc0d8\ub9ac\ube59\uc2a4\ud134 \uc591\uc5b4\uc7a5\uc740 \uc1a1\uc5b4\ub97c \uc54c\uc5d0\uc11c \uc5b4\ub9b0 \ubb3c\uace0\uae30\uae4c\uc9c0 \uae30\ub974\ub294 \uacf3\uc774\uc57c\n\uadf8 \ubb3c\uace0\uae30\ub4e4\uc740 \uc54c\ubc84\ud0c0\uc758 \ud638\uc218\uc640 \uc5f0\ubabb\uc5d0 \ud480\uc5b4\uc8fc\ub294 \uc0ac\uc5c5\uc73c\ub85c \uc774\uc5b4\uc838\n\uc608\uc804\uc5d4 \ubb3c\uace0\uae30 \uc774\ub984\ub9cc \uc678\uc6e0\ub294\ub370 \uc774\ubc88\uc5d4 \ubb3c\uac00\uc5d0 \uc624\uae30 \uc804 \uacfc\uc815\ubd80\ud130 \uae30\uc5b5\ud560 \uac70\uc57c\n\ub0b4 \uc0dd\ud0dc \uacf5\ubd80\uac00 \uc218\uc870 \uc55e\uc5d0\uc11c \ub05d\ub0a0 \uc21c \uc5c6\uc796\uc544 \u314b\u314b", "expected_views": 18, "old_view_pulses": [{"views": 18, "bucket": "2026-10-06T19:40:00+00:00"}]}]$FIX$::jsonb)
as x(id uuid,old_created_at timestamptz,new_created_at timestamptz,author_id uuid,city_id text,expected_title text,expected_body text,expected_views int,old_view_pulses jsonb);
do $$ begin
 perform 1 from public.posts p join city_date_fix f on f.id=p.id for update of p;
 if (select count(*) from public.posts p join city_date_fix f on f.id=p.id
     join public.profiles pr on pr.id=p.author_id join auth.users u on u.id=pr.id
     where p.created_at=f.old_created_at and p.author_id=f.author_id and p.city_id=f.city_id
       and p.title=f.expected_title and p.body=f.expected_body and p.view_count=f.expected_views and p.status='published'
       and pr.city_id=p.city_id and pr.account_status='active' and u.email like '%@seed.gling.invalid') <> 23 then
   raise exception 'CITY_DATE_FIX_CONCURRENT_CHANGE';
 end if;
end $$;
update public.posts p set created_at=f.new_created_at,
 posted_on=(f.new_created_at at time zone city.timezone)::date
from city_date_fix f,public.cities city where p.id=f.id and city.id=p.city_id;
update private.post_view_pulse pulse
set bucket=date_bin(interval '10 minutes',f.new_created_at,'2000-01-01'::timestamptz)
from city_date_fix f
where pulse.post_id=f.id
 and pulse.bucket=date_bin(interval '10 minutes',f.old_created_at,'2000-01-01'::timestamptz)
 and exists(select 1 from jsonb_to_recordset(f.old_view_pulses) as old(bucket timestamptz,views int)
            where old.bucket=pulse.bucket and old.views=pulse.views);
commit;